 public static void Style(Form f,string title,int w,int h){f.Text=title;f.Size=new Size(w,h);f.StartPosition=FormStartPosition.CenterParent;f.BackColor=Bg;f.ForeColor=Text;f.Font=Font(9);f.AutoScaleMode=AutoScaleMode.Dpi;f.Icon=App.MakeIcon();}
 internal static Action<Exception> ErrorSink;
 public static void Error(Exception e){ErrorLog.Record(e);if(ErrorSink!=null){ErrorSink(e);return;}MessageBox.Show(e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
 public static void Open(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
