public class Preview : Control {
 IntPtr handle; Cursor live; uint frame;uint steps=1; System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer(); public bool Playground; public string FileName=""; public Size NativeSize=Size.Empty;
 public Preview(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);timer.Interval=83;timer.Tick+=(s,e)=>{frame++;Invalidate();};timer.Start();BackColor=Theme.Panel;}
 public void LoadFile(string file,int targetSize=0){if(IsDisposed)return;Release();FileName=file;frame=0;steps=1;try{if(File.Exists(file)){if(new FileInfo(file).Length>8*1024*1024)throw new InvalidDataException("预览光标文件过大");if(Path.GetExtension(file).ToLowerInvariant()==".ani"){byte[] bytes=File.ReadAllBytes(file);for(int i=12;i+44<=bytes.Length;i++){if(Encoding.ASCII.GetString(bytes,i,4)=="anih"){steps=Math.Max(1,BitConverter.ToUInt32(bytes,i+16));break;}}}handle=Native.LoadExactCursor(file);if(handle!=IntPtr.Zero){NativeSize=Native.CursorDimensions(handle);if(targetSize>0&&Math.Max(NativeSize.Width,NativeSize.Height)!=targetSize){double scale=(double)targetSize/Math.Max(NativeSize.Width,NativeSize.Height);int w=Math.Max(1,(int)Math.Round(NativeSize.Width*scale)),h=Math.Max(1,(int)Math.Round(NativeSize.Height*scale));Native.DestroyCursor(handle);handle=IntPtr.Zero;handle=Native.LoadExactCursor(file,w,h);NativeSize=Native.CursorDimensions(handle);}live=new Cursor(handle);if(Playground)Cursor=live;}}}catch(Exception error){ErrorLog.Record(error);Release();}Invalidate();}
 void Release(){NativeSize=Size.Empty;Cursor=Cursors.Default;if(live!=null){live.Dispose();live=null;}if(handle!=IntPtr.Zero){Native.DestroyCursor(handle);handle=IntPtr.Zero;}}
 protected override void Dispose(bool disposing){if(disposing){timer.Dispose();Release();}base.Dispose(disposing);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;using(var pen=new Pen(Color.FromArgb(65,Theme.Muted)))for(int x=18;x<Width;x+=24)for(int y=18;y<Height;y+=24)g.DrawEllipse(pen,x,y,1,1);
  if(handle!=IntPtr.Zero){int w=NativeSize.Width,h=NativeSize.Height;float fit=Math.Min(1f,Math.Min((Width-20f)/Math.Max(1,w),(Height-(Playground?48f:12f))/Math.Max(1,h)));w=Math.Max(1,(int)Math.Round(w*fit));h=Math.Max(1,(int)Math.Round(h*fit));IntPtr dc=g.GetHdc();try{Native.DrawIconEx(dc,(Width-w)/2,(Height-h)/2-(Playground?12:0),handle,w,h,frame%steps,IntPtr.Zero,3);}finally{g.ReleaseHdc(dc);}}
  if(Playground)using(var font=Theme.Font(8))TextRenderer.DrawText(g,"移入这里，体验真实光标",font,new Rectangle(0,Height-32,Width,22),Theme.Muted,TextFormatFlags.HorizontalCenter);
 }
}
