 public void Run(Action action,string message){if(IsDisposed||Disposing)return;CancelSizeWork();try{action();status.Text=message;RefreshCards();if(selected!=null)SelectSkin(selected);}catch(Exception e){status.Text="操作失败："+e.Message;Theme.Error(e);}}
 void RefreshCards(){if(cards==null)return;cards.SuspendLayout();foreach(Control c in cards.Controls.Cast<Control>().ToArray())c.Dispose();cards.Controls.Clear();string query=search.Text.Trim();var list=store.Pref.Skins.Where(s=>(query.Length==0||(s.Name+" "+s.Description).IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)&&(filter!="我的收藏"||s.Favorite)&&(filter!="动态皮肤"||s.Animated)&&(filter!="静态皮肤"||!s.Animated)&&(filter!="本地导入"||s.Builtin<0)&&(filter!="趣味造型"||s.Builtin>=8)&&(filter!="新款皮肤"||s.Builtin>=39)&&(filter!="最近使用"||s.LastUsed>0)).ToList();list=SortSkins(list);foreach(var s in list){var card=new SkinCard(s,Math.Max(0,store.SkinSize(s))){Selected=selected!=null&&selected.Id==s.Id};card.Chosen+=(o,e)=>SelectSkin(((SkinCard)o).Skin);card.Applied+=(o,e)=>QuickApply(((SkinCard)o).Skin);cards.Controls.Add(card);}if(list.Count==0){var empty=Theme.Label("没有匹配的皮肤\n\n试试其他名称，或导入你的第一款皮肤。",11,Theme.Muted);empty.Margin=new Padding(12,30,0,0);cards.Controls.Add(empty);}cards.ResumeLayout();}
