 void ChooseImport(){using(var d=new OpenFileDialog{Title="导入皮肤（可多选 / 可拖入窗口）",Filter="光标、压缩包或图片|*.cur;*.ani;*.zip;*.png;*.gif;*.bmp;*.jpg;*.jpeg;*.ico|所有文件|*.*",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK)ImportFiles(d.FileNames);}
 public void ImportFiles(string[] files){int size=store.Pref.Size,hx=0,hy=0;bool images=files.Any(f=>new[]{".png",".gif",".bmp",".jpg",".jpeg",".ico"}.Contains(Path.GetExtension(f).ToLowerInvariant()));if(images)using(var options=new ImageOptions(size)){if(options.ShowDialog(this)!=DialogResult.OK)return;size=options.ImageSize;hx=options.HotX;hy=options.HotY;}
  Run(()=>{Skin last=null;foreach(var zip in files.Where(f=>Path.GetExtension(f).ToLowerInvariant()==".zip"))last=store.Import(new[]{zip},size,hx,hy);var loose=files.Where(f=>Path.GetExtension(f).ToLowerInvariant()!=".zip").ToArray();if(loose.Length>0)last=store.Import(loose,size,hx,hy);if(last!=null)selected=last;},"导入完成 · 可在角色映射中检查后应用");}
 void Export(Skin s){using(var d=new SaveFileDialog{Title="导出原生皮肤包",Filter="ZIP 皮肤包|*.zip",FileName=Store.SafeName(s.Name)+".zip"})if(d.ShowDialog(this)==DialogResult.OK)Run(()=>store.Export(s,d.FileName),"已导出："+d.FileName);}
 void RandomSkin(){var pool=store.Pref.Skins.Where(v=>(!store.Pref.FavoritesOnly||v.Favorite)&&v.Id!=store.Pref.Active).ToList();pool=pool.Where(store.Available).ToList();if(pool.Count==0){status.Text="没有可轮换的其他皮肤，请添加收藏或关闭仅轮换收藏。";return;}var s=pool[random.Next(pool.Count)];QuickApply(s);}
 void OpenSettings(){int previousSize=store.Pref.Size;using(var d=new SettingsDialog(store)){if(d.ShowDialog(this)==DialogResult.OK){store.Save();RefreshStartupSwitch();BindKeys();nextRotate=DateTime.Now.AddMinutes(store.Pref.RotationMinutes);foreach(var skin in store.Pref.Skins)skin.PreviewRoles=null;RefreshCards();SelectSkin(selected);var active=store.Pref.Skins.FirstOrDefault(v=>v.Id==store.Pref.Active);if(active!=null&&active.SizeOverride==0)QuickApply(active);else {SizeTask=ResizeSkinAsync(selected,false);if(active!=null&&active.SizeOverride!=0&&previousSize!=store.Pref.Size)status.Text="全局尺寸已保存；当前皮肤使用独立尺寸，可在右侧选择跟随全局，或在设置中勾选重置独立尺寸。";}}}}
 void Download(){using(var d=new DownloadDialog(store)){if(d.ShowDialog(this)==DialogResult.OK&&d.ResultFiles!=null){try{ImportFiles(d.ResultFiles);}finally{try{Directory.Delete(d.TempDirectory,true);}catch{}}}}}
 void Help(){MessageBox.Show("Cursor Atelier / 光标工坊 1.6.3\n\n1. 选择皮肤，移入预览区体验，再点「应用到 Windows」。\n2. Sweezy 下载 Windows Cursor、Windows Pointer 或 Complete Pack ZIP，拖入本窗口。\n3. 也可粘贴 Sweezy 单个皮肤页面链接下载；网站验证或限流时请改用浏览器下载后导入。\n4. CUR / ANI 支持四档缩放，热点等比调整并保留动画；PNG / GIF 可转换。\n5. 导入后可修改 17 个角色映射；缺失角色沿用原来方案。\n6. 首次应用自动备份原方案；撤销支持在最近两个方案间切换。\n7. Ctrl+Alt+R 恢复；Ctrl+Alt+N 随机；Ctrl+Alt+S 显示窗口。\n8. 主题配色支持六套外观和自定义强调色；关于窗口可查看作者联系方式与 GitHub 开源地址（github.com/jingpanlong/CursorAtelier）。\n9. 双击卡片应用，最近使用可快速回找；更多工具中可复制、批量备份和暂停轮换。\n10. 趣味造型使用左上角同色小三角尖端作为点击热点。\n11. 右侧可为单款皮肤调节尺寸，偏好设置可调全局尺寸。生成在后台执行，当前皮肤自动更新；导入原文件保留。\n\n应用会写入当前用户的 Windows 光标设置；部分游戏或自绘光标程序使用自己的光标。点击叉号收起到托盘，程序仍运行并保留指针；右键托盘选择退出或点击底部退出按钮，才恢复 Windows 默认指针。\n\n本软件独立开发，与 Sweezy 无隶属关系。导入的第三方皮肤版权归原作者。","使用指南",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 public void CaptureTo(string target){DrawToBitmapAndSave(target);}
 void DrawToBitmapAndSave(string target){using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(Point.Empty,Size));bitmap.Save(target);}}
}
public class MappingDialog:Form {
 Skin skin;TextBox name;List<ComboBox> boxes=new List<ComboBox>();List<string> files;
 public MappingDialog(Store store,Skin s){skin=s;Theme.Style(this,"角色映射 · "+s.Name,650,710);MinimumSize=Size;MaximumSize=Size;
  name=new TextBox{BackColor=Theme.Raised,ForeColor=Theme.Text,Text=s.Name,Location=new Point(24,24),Width=580,MaxLength=60};Controls.Add(name);var hint=Theme.Label("未设置的角色沿用原来方案。普通选择必须设置。",9,Theme.Muted);hint.Location=new Point(24,63);Controls.Add(hint);var panel=new Panel{Location=new Point(24,99),Size=new Size(580,488),AutoScroll=true};Controls.Add(panel);
  files=(Directory.Exists(Path.Combine(store.Root,"library",s.Id))?Directory.GetFiles(Path.Combine(store.Root,"library",s.Id)):new string[0]).Where(p=>new[]{".cur",".ani"}.Contains(Path.GetExtension(p).ToLowerInvariant())).ToList();for(int i=0;i<Store.Roles.Length;i++){string r=Store.Roles[i];var l=Theme.Label(Store.Labels[i],9,Theme.Text);l.Location=new Point(0,i*40+5);panel.Controls.Add(l);var b=new DarkCombo{Location=new Point(116,i*40),Width=436,DropDownStyle=ComboBoxStyle.DropDownList};b.Items.Add("（沿用原来方案）");foreach(var f in files)b.Items.Add(Path.GetFileName(f));b.SelectedIndex=s.Roles.ContainsKey(r)?files.IndexOf(s.Roles[r])+1:0;boxes.Add(b);panel.Controls.Add(b);}
  var save=Theme.Button("保存映射",(o,e)=>{if(name.Text.Trim().Length==0){MessageBox.Show("请输入皮肤名称");return;}if(boxes[0].SelectedIndex==0){MessageBox.Show("请设置普通选择");return;}var roles=new Dictionary<string,string>();for(int i=0;i<boxes.Count;i++)if(boxes[i].SelectedIndex>0)roles[Store.Roles[i]]=files[boxes[i].SelectedIndex-1];skin.Name=name.Text.Trim();skin.PreviewRoles=null;skin.Roles=roles;DialogResult=DialogResult.OK;},true);save.Location=new Point(472,611);Controls.Add(save);
 }
}
