public class DownloadDialog:Form {
 TextBox input;Label status;Button start;CheckBox proxyOption;CancellationTokenSource cts=new CancellationTokenSource();public string[] ResultFiles;public string TempDirectory;
 public async Task<string[]> TestDownload(string url){input.Text=url;await Go(downloadStore);if(IsDisposed||closing)throw new OperationCanceledException();if(ResultFiles==null)throw new InvalidDataException(status.Text);return ResultFiles;}
 Store downloadStore;bool busy,closing;internal Func<Uri,int,CancellationToken,Task<byte[]>> TestTransport;
 public DownloadDialog(Store store){downloadStore=store;Theme.Style(this,"从链接下载皮肤",660,350);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;var hint=Theme.Label("粘贴 Sweezy 单款皮肤页面，或 HTTPS 的 CUR / ANI / ZIP 直链。",10,Theme.Text);hint.Location=new Point(23,25);Controls.Add(hint);input=new TextBox{BackColor=Theme.Raised,ForeColor=Theme.Text,Location=new Point(24,74),Width=590};Controls.Add(input);status=Theme.Label("下载完成后导入皮肤库，不会自动应用。\n网络验证或限流时，可用浏览器下载后拖入主窗口。",9,Theme.Muted);status.Location=new Point(24,122);status.MaximumSize=new Size(590,90);Controls.Add(status);start=Theme.Button("下载并导入",async(o,e)=>await Go(store),true);start.SetBounds(24,223,590,40);Controls.Add(start);FormClosing+=(o,e)=>{closing=true;cts.Cancel();if(!busy)cts.Dispose();};}
 protected override void OnLoad(EventArgs e){base.OnLoad(e);proxyOption=new CheckBox{Text="使用系统代理（网络需要代理时勾选）",Location=new Point(24,181),Width=590,Height=28,ForeColor=Theme.Muted};Controls.Add(proxyOption);}
 async Task<byte[]> Fetch(HttpClient client,Uri uri,int limit){if(TestTransport!=null){var data=await TestTransport(uri,limit,cts.Token);if(data.Length>limit)throw new InvalidDataException("下载文件过大");return data;}using(var response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,cts.Token)){response.EnsureSuccessStatusCode();if(response.RequestMessage.RequestUri.Scheme!="https")throw new InvalidDataException("只支持 HTTPS 下载");if(response.Content.Headers.ContentLength>limit)throw new InvalidDataException("下载文件过大");using(var stream=await response.Content.ReadAsStreamAsync())using(var ms=new MemoryStream()){byte[] buffer=new byte[16384];int n;while((n=await stream.ReadAsync(buffer,0,buffer.Length,cts.Token))>0){if(ms.Length+n>limit)throw new InvalidDataException("下载超过大小限制");ms.Write(buffer,0,n);}return ms.ToArray();}}}
 async Task Go(Store store){if(busy||closing||IsDisposed)return;Uri uri;if(!Uri.TryCreate(input.Text.Trim(),UriKind.Absolute,out uri)||uri.Scheme!="https"){status.Text="请输入完整的 HTTPS 链接。";return;}busy=true;ResultFiles=null;start.Enabled=false;status.Text="正在下载… 关闭此窗口可取消。";
  try{cts.Dispose();cts=new CancellationTokenSource();cts.CancelAfter(TimeSpan.FromSeconds(90));TempDirectory=Path.Combine(store.Root,"downloads",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(TempDirectory);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
   using(var handler=new HttpClientHandler{UseProxy=proxyOption!=null&&proxyOption.Checked,AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate})using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromSeconds(40);client.DefaultRequestHeaders.UserAgent.ParseAdd("CursorAtelier/1.2");byte[] data=await Fetch(client,uri,64*1024*1024);CheckOpen();var urls=new List<Uri>();string html=Encoding.UTF8.GetString(data);
    if(data.Length>0&&html.IndexOf("<html",StringComparison.OrdinalIgnoreCase)>=0){if(uri.Host!="sweezy-cursors.com"&&uri.Host!="www.sweezy-cursors.com")throw new InvalidDataException("网页解析仅支持 Sweezy 单款皮肤页；其他网站请使用文件直链。");string marker=uri.AbsolutePath.TrimEnd('/')+"/downloads/";foreach(string part in new[]{"windows-cursor/","windows-pointer/"}){var match=Regex.Match(html,"href=[\"']([^\"']*"+Regex.Escape(marker+part)+")[\"']",RegexOptions.IgnoreCase);if(match.Success)urls.Add(new Uri(uri,WebUtility.HtmlDecode(match.Groups[1].Value)));}if(urls.Count==0)throw new InvalidDataException("未找到 Windows 下载链接，请使用单款详情页或下载文件后导入。");}
    var list=new List<string>();if(urls.Count==0)list.Add(SaveBytes(data,"download"));else for(int i=0;i<urls.Count;i++){CheckOpen();status.Text="正在下载 Windows 光标 "+(i+1)+" / "+urls.Count;data=await Fetch(client,urls[i],64*1024*1024);CheckOpen();list.Add(SaveBytes(data,i==0?"cursor":"pointer"));}CheckOpen();ResultFiles=list.ToArray();DialogResult=DialogResult.OK;
   }
  }catch(Exception e){if(!closing&&!IsDisposed&&!Disposing){status.Text=e is OperationCanceledException?"下载已取消或超时。":"下载失败："+e.Message;start.Enabled=true;}CleanupDownload(store);if(!(e is OperationCanceledException))ErrorLog.Record(e);}
  finally{busy=false;if(closing)cts.Dispose();}
 }
 void CheckOpen(){if(closing||IsDisposed||Disposing)throw new OperationCanceledException();cts.Token.ThrowIfCancellationRequested();}
 void CleanupDownload(Store store){try{if(string.IsNullOrEmpty(TempDirectory))return;string full=Path.GetFullPath(TempDirectory),prefix=Path.GetFullPath(Path.Combine(store.Root,"downloads"))+Path.DirectorySeparatorChar;if(full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&Directory.Exists(full))Directory.Delete(full,true);}catch(Exception error){ErrorLog.Record(error);}}

 string SaveBytes(byte[] b,string name){string ext=b.Length>4&&b[0]==80&&b[1]==75?".zip":b.Length>12&&Encoding.ASCII.GetString(b,0,4)=="RIFF"?".ani":b.Length>6&&b[0]==0&&b[1]==0&&b[2]==2&&b[3]==0?".cur":null;if(ext==null)throw new InvalidDataException("服务器未返回 CUR、ANI 或 ZIP 文件（可能需要浏览器验证）");string path=Path.Combine(TempDirectory,name+ext);File.WriteAllBytes(path,b);return path;}
}
}
